import * as THREE from 'three/webgpu';
import { color, mix, positionLocal, float } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const timelines = [];
  const disposables = [];
  const meshes = [];

  // Color palette
  const colors = {
    background: 0x0b0b10,
    surface: 0x14141a,
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
  };

  // ========== BACKGROUND PLANE ==========
  const bgGeometry = new THREE.PlaneGeometry(7, 5.5);
  const gradientNode = mix(
    color(new THREE.Color(colors.background)),
    color(new THREE.Color(colors.surface)),
    positionLocal.y.add(2.75).div(5.5)
  );
  const bgMaterial = new THREE.MeshBasicNodeMaterial({
    colorNode: gradientNode,
  });
  const bgMesh = new THREE.Mesh(bgGeometry, bgMaterial);
  bgMesh.position.z = -0.05;
  group.add(bgMesh);
  disposables.push(bgGeometry, bgMaterial);

  // ========== TEXT ELEMENTS ==========
  const setMeshOpacity = (mesh, opacity) => {
    if (mesh.material) {
      mesh.material.transparent = true;
      mesh.material.opacity = opacity;
    } else if (mesh.children) {
      mesh.children.forEach(child => {
        if (child.material) {
          child.material.transparent = true;
          child.material.opacity = opacity;
        }
      });
    }
  };

  const createText = (text, fontConfig, position, isHero = false) => {
    const textMesh = ctx.fontAtlas({
      text,
      ...fontConfig,
      color: new THREE.Color(colors.paper),
    });

    textMesh.position.copy(position);
    setMeshOpacity(textMesh, 0);
    group.add(textMesh);
    meshes.push(textMesh);

    if (isHero) {
      const shadowMesh = ctx.fontAtlas({
        text,
        ...fontConfig,
        color: new THREE.Color(colors.ink),
      });
      shadowMesh.position.copy(position);
      shadowMesh.position.z -= 0.02;
      setMeshOpacity(shadowMesh, 0);
      group.add(shadowMesh);
      meshes.push(shadowMesh);
    }

    return textMesh;
  };

  const kickerMesh = createText(
    "NOVA ATELIER / JOURNAL",
    { fontFamily: "JetBrains Mono", fontSize: 0.09, fontWeight: 700, letterSpacing: 0.12 },
    new THREE.Vector3(-3.1, 1.7, 0.01)
  );

  const heroLine1Mesh = createText(
    "PRECISION IS",
    { fontFamily: "Lora", fontSize: 0.62, fontWeight: 600, letterSpacing: -0.015 },
    new THREE.Vector3(-3.1, 0.9, 0.01),
    true
  );

  const heroLine2Mesh = createText(
    "A HABIT.",
    { fontFamily: "Lora", fontSize: 0.62, fontWeight: 600, letterSpacing: -0.015 },
    new THREE.Vector3(-3.1, 0.25, 0.01),
    true
  );

  const bodyMesh = createText(
    "Notes from the bench: tolerances, tempering, and the case for slower watchmaking.",
    { fontFamily: "JetBrains Mono", fontSize: 0.13, fontWeight: 400, letterSpacing: 0, maxWidth: 4.5 },
    new THREE.Vector3(-3.1, -0.8, 0.01)
  );

  const captionMesh = createText(
    "ISSUE 12 / JULY 2026",
    { fontFamily: "JetBrains Mono", fontSize: 0.09, fontWeight: 400, letterSpacing: 0.08 },
    new THREE.Vector3(-3.1, -1.9, 0.01)
  );

  // ========== ACCENT UNDERLINE RULE ==========
  const ruleGeometry = new THREE.PlaneGeometry(2.2, 0.05);
  const ruleMaterial = new THREE.MeshStandardNodeMaterial({
    colorNode: color(new THREE.Color(colors.accent)),
    emissiveNode: color(new THREE.Color(colors.accent)),
    emissiveIntensityNode: float(1.2),
    roughnessNode: float(1.0),
    metalnessNode: float(0),
  });
  const ruleMesh = new THREE.Mesh(ruleGeometry, ruleMaterial);
  ruleMesh.position.set(-3.1 + 2.2 / 2, -0.15, 0.02);
  ruleMesh.scale.x = 0;
  group.add(ruleMesh);
  disposables.push(ruleGeometry, ruleMaterial);

  // ========== ANIMATIONS ==========
  const tl = gsap.timeline();
  const blocks = [
    { mesh: kickerMesh, y: 1.7 },
    { mesh: heroLine1Mesh, y: 0.9 },
    { mesh: heroLine2Mesh, y: 0.25 },
    { mesh: bodyMesh, y: -0.8 },
    { mesh: captionMesh, y: -1.9 },
  ];

  blocks.forEach(({ mesh, y }, index) => {
    const delay = index * 0.08;
    const startY = y + 0.4;

    tl.from(mesh.position, {
      y: startY,
      duration: 0.7,
      ease: "power3.out",
    }, delay);

    if (mesh.material) {
      tl.to(mesh.material, {
        opacity: 1,
        duration: 0.7,
        ease: "power3.out",
      }, delay);
    } else if (mesh.children) {
      mesh.children.forEach(child => {
        if (child.material) {
          tl.to(child.material, {
            opacity: 1,
            duration: 0.7,
            ease: "power3.out",
          }, delay);
        }
      });
    }
  });

  tl.to(ruleMesh.scale, {
    x: 1,
    duration: 0.5,
    ease: "back.out",
  }, 0.7);

  timelines.push(tl);

  // ========== CLEANUP ==========
  group.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    disposables.forEach(r => r?.dispose?.());
    meshes.forEach(m => {
      m.geometry?.dispose?.();
      if (Array.isArray(m.material)) {
        m.material.forEach(mat => mat?.dispose?.());
      } else {
        m.material?.dispose?.();
      }
    });
  };

  group.userData.handlers = {};

  return group;
}
